window.__BUNDLE__={"generatedAt":"2026-08-26T13:41:34.152985+00:00","recentDays":7,"archiveDays":1825,"recentCutoff":"2026-08-19","archiveCutoff":"2021-08-27","addedToday":1,"addedThisRun":1,"fetchStats":{"hf":208,"arxiv":1276,"total":1484},"freshness":{"latestPaperDate":"2026-08-26","latestPublishedDate":"2026-08-26","latestBatchCount":284,"newInLast24h":307,"newInLast48h":833},"historyTotal":9040,"topicCounts":{"Multi-Agent":1689,"Evaluation":4589,"Planning":816,"Memory":204,"Code Agent":474,"Interpretability":311,"Agentic RAG":928,"Agentic Search":1126,"RL for LLM":699,"Reasoning":2860,"Hallucination":559,"Post-Training":1306,"Alignment":1204,"World Model":99,"Tool Use":1010,"Agent Safety":1970,"Computer Use":202,"Reflection":402,"VLM Training":421,"LLM Training":972,"Fine-tuning":1303,"Multimodal Agent":57,"Agent Framework":613,"Error Attribution":80,"Data Engine":199},"count":36,"recentTotal":1721,"archiveCount":0,"archiveTotal":7319,"sources":{"hf":30,"arxiv":1689,"semanticScholar":2},"archiveSources":{"hf":0,"arxiv":0,"semanticScholar":0},"warnings":[],"notes":["archive is split by year under data/archive/ for fast lazy loading; data/history.json keeps the complete database"],"papers":[{"source":"hf","topics":["Reasoning","Planning","Evaluation"],"authors":["Bin Zhang","Bowen Zheng","Chao Yi","Chengyu Lai","Dian Chen","Dimin Wang","Gaoyang Guo","Jialin Zhu","Jian Wu","Jing Yu","Jiuning Lin","Lingqing Zhang","Lingyun Zheng","Mao Zhang","Mingming Pan","Ruiquan Lan","Shuai Zhong","Wen Chen","Wendong Zhang","Xiaodong Zhu","Xuan Chen","Xunke Xi","Yifan Lu","Yiheng Wang","Yue Zeng","Yujie Luo","Yuning Jiang","Zhe Hu","Zhibo Xiao","Zihong Huang","Binbin Cao","Bo Zheng","Danning Wang","Dixuan Wang","Ge Fan","Haixia Wu","Han Zhu","Hao Fang","Haoming Chen","Huiping Chu","Jian Wang","Jianjun Wu","Jiawei Wu","Jiaxin Yu","Jingwen Liu","Jinzhe Shan","Kai Meng","Kai Zhang","Keqin Xu","Kewei Zhu","Lang Tian","Leihui Chen","Li Chen","Licheng Xu","Lide Xiao","Ruitong Zhang","Shiyao Peng","Silu Zhou","Tao Wang","Wei Shi","Wenjun Yang","Xiang Chen","Xiang Gao","Xiao Ren","Xu Liu","Xuwen Wang","Yang Li","Yeqiu Yang","Yi Hu","Yichen Yuan","Yinnan Song","Yipeng Yu","Yuan Liu","Yunqi Gao","Zhiliang Huang","Zhujin Gao","Zongyuan Wu"],"hfUrl":"https://huggingface.co/papers/2608.09408","date":"2026-08-26","title":"DREAM Technical Report","upvotes":3,"pdf":"https://arxiv.org/pdf/2608.09408.pdf","url":"https://arxiv.org/abs/2608.09408","arxiv":"https://arxiv.org/abs/2608.09408","tags":["Reasoning","Planning","Evaluation"],"id":"arxiv:2608.09408","abstract":"Industrial recommender systems commonly use cascaded retrieval, ranking, and re-ranking pipelines. Although efficient, these pipelines fragment information and objectives across modules, rely on rigid rules, and have limited awareness of real-time intent, leaving session-level shifts among browsing, comparison, and purchase insufficiently addressed. We present DREAM (Developing Recommender Engine with Agentic Methods), an autonomous optimization control architecture that adds a perception-aware, orchestrable, and auditable policy layer atop existing pipelines without replacing them. DREAM has two core components. First, a three-tier Intent Engine fuses on-device signals into structured L0/L1/L2 intent representations; its edge-cloud trigger chain reduces reporting volume to approximately 8.7%. Second, a Meta Engine uses a MetaModel for layered M1-to-M2-to-M3 reasoning: intent summarizati"},{"source":"arxiv","topics":["Evaluation","Alignment"],"authors":["Junjie Zhou","Ke Mei","Lei Li","Tianyi Wang","Fengyun Rao","Jing Lyu"],"submittedDate":"2026-08-25","hfUrl":"https://huggingface.co/papers/2608.24053","date":"2026-08-26","title":"WeMM-Embedding: WeChat Multi-Modal Embedding Technical Report","announceDate":"2026-08-26","upvotes":52,"pdf":"https://arxiv.org/pdf/2608.24053.pdf","url":"https://arxiv.org/abs/2608.24053","arxiv":"https://arxiv.org/abs/2608.24053","tags":["Evaluation","Alignment"],"id":"arxiv:2608.24053","abstract":"Universal multimodal embeddings are becoming a core component of modern AI systems, enabling heterogeneous content to be represented in a shared space for applications such as retrieval, recommendation, classification, and agentic systems. In this report, we present WeMM-Embedding, a family of universal multimodal embedding models supporting text, images, videos, visual documents, and arbitrarily interleaved multimodal inputs with flexible output dimensions. The family comprises 2B, 4B, and 9B variants and is trained in two stages: a large-scale multimodal alignment stage, followed by a refinement stage using curated data, fine-grained relevance supervision, and cross-scale knowledge transfer. Across extensive evaluations, WeMM-Embedding achieves leading performance on multiple public benchmarks. Notably, the 2B variant already surpasses the previously leading 8B open-source baseline on "},{"source":"arxiv","topics":["Post-Training","Alignment"],"authors":["Wei Zhou","Xiongwei Zhu","Lingdong Kong","Bo Chen","Lei Zhang","Yongyuan Liang","Xiaoxia Hou","Ye Tian","Xian Sun","Yingshuo Wang","Linfeng Li","Shengqiong Wu","Leigang Qu","Feng Li","Wei Liu","Julian McAuley","Tat-Seng Chua"],"submittedDate":"2026-08-25","hfUrl":"https://huggingface.co/papers/2608.24646","date":"2026-08-26","title":"On-Policy Self-Distillation in Diffusion Models","announceDate":"2026-08-26","upvotes":44,"pdf":"https://arxiv.org/pdf/2608.24646.pdf","url":"https://arxiv.org/abs/2608.24646","arxiv":"https://arxiv.org/abs/2608.24646","tags":["Post-Training","Alignment"],"id":"arxiv:2608.24646","abstract":"Reinforcement learning can align diffusion models with human preferences and task-specific objectives, but endpoint rewards do not specify how an intermediate denoising prediction should change. We introduce DiffusionOPSD as an on-policy self-distillation framework that converts image-level reward guidance into explicit targets for clean-output predictions at sampled queries. At each outer iteration, a frozen behavior policy generates trajectories and supplies query states and anchors. Reward gradients construct bounded positive and negative targets around each anchor. The trainable policy fits these targets as detached supervision through finite fitting before an exponential moving average update refreshes the behavior policy. This setup lets us measure target construction and finite realization separately. Controlled same-query experiments show that larger target-construction gains do "},{"source":"arxiv","topics":["Memory","Evaluation","Reflection"],"authors":["Zhaochen Yu","Yingcheng Wu","Zhenfei Yin","Kaiyuan Chen","Zhe Zhao","Mengdi Wang","Shuicheng Yan","Ling Yang"],"submittedDate":"2026-08-25","hfUrl":"https://huggingface.co/papers/2608.24876","date":"2026-08-26","title":"Recursive Experiential-Working Memory Evolution for Long-Horizon Agent Harnesses","announceDate":"2026-08-26","upvotes":16,"pdf":"https://arxiv.org/pdf/2608.24876.pdf","url":"https://arxiv.org/abs/2608.24876","arxiv":"https://arxiv.org/abs/2608.24876","tags":["Memory","Evaluation","Reflection"],"id":"arxiv:2608.24876","abstract":"Recursive self-improvement (RSI) remains hard in long-horizon tasks, where growing histories obscure the task state and misalign skill invocation. We introduce Recuris, a recursive Experiential-Working Memory architecture for long-horizon agent harnesses, in which Working Memory tracks task progress and guides skill selection from Experiential Memory, grounding skill use in current needs rather than the full history. This coupling also turns execution into structured evidence that localizes failures to specific memory components. Across tasks, a fixed Meta-Agent turns that evidence into localized, validation-gated updates to Skill Memory that reshape execution and yield new evidence, forming a bounded recursive memory-evolution loop. Across four long-horizon benchmarks and ten models, Recuris improves task success in 35 of the 37 completed model-benchmark pairs, carrying frontier models "},{"source":"arxiv","topics":["Post-Training","Reasoning","Evaluation","RL for LLM"],"authors":["Wenze Lin","Jiale Zhao","Xitai Jiang","Songde Rao","Yining Li","Shenzhi Wang","Bingxiang He","Gao Huang"],"submittedDate":"2026-08-25","hfUrl":"https://huggingface.co/papers/2608.24696","date":"2026-08-26","title":"On-policy Distillation with Verifiable Reward","announceDate":"2026-08-26","upvotes":9,"pdf":"https://arxiv.org/pdf/2608.24696.pdf","url":"https://arxiv.org/abs/2608.24696","arxiv":"https://arxiv.org/abs/2608.24696","tags":["Post-Training","Reasoning","Evaluation","RL for LLM"],"id":"arxiv:2608.24696","abstract":"Reinforcement Learning with Verifiable Rewards (RLVR) and on-policy distillation (OPD) have become two widely adopted paradigms for post-training large language models. However, RLVR suffers from sparse task-level feedback, while OPD provides dense token-level guidance but ignores trajectory correctness, limiting its performance to that of the teacher. Combining them is a promising direction: OPD supplies dense supervisory signals, while RLVR provides task-level correctness. Nevertheless, existing integrations often rely on weighted combination or heuristic switching, introducing extra hyperparameters and trade-offs. We propose On-policy Distillation with Verifiable Reward (OPDVR), a simple yet effective method that seamlessly combines OPD and RLVR without adding any hyperparameters. We first reformulate the implicit reward of sampled-token OPD based on trajectory correctness, then apply"},{"source":"arxiv","topics":["Evaluation"],"authors":["Jiangning Zhang","Haojun Chen","Yong Liu"],"submittedDate":"2026-08-25","hfUrl":"https://huggingface.co/papers/2608.24877","date":"2026-08-26","title":"From Seeing to Acting: Smart Glasses as First-Person Intelligence Platforms","announceDate":"2026-08-26","upvotes":8,"pdf":"https://arxiv.org/pdf/2608.24877.pdf","url":"https://arxiv.org/abs/2608.24877","arxiv":"https://arxiv.org/abs/2608.24877","tags":["Evaluation"],"id":"arxiv:2608.24877","abstract":"Smart glasses are evolving from capture and display accessories into first-person intelligence platforms that connect human perception, persistent context, and digital or physical action. Their on-body viewpoint aligns with the wearer's vision, audition, motion, and hand-object interaction, but must operate under tight energy, thermal, privacy, and feedback constraints. Despite rapid progress in augmented reality, egocentric vision, multimodal models, human-computer interaction, and embodied intelligence, the literature remains fragmented across devices, tasks, and benchmarks. \\textit{The key challenge is not whether a model can recognize, answer, remember, or act in isolation, but whether a complete system can sustain a reliable, temporally valid, correctable, and governable perception-state-interaction-action loop.} This survey is \\textit{the \\textbf{first} to systematically study smar"},{"source":"arxiv","topics":["LLM Training","Evaluation","World Model"],"authors":["Wenxuan Shen","Dongna Jin","Dongping Chen"],"submittedDate":"2026-08-25","hfUrl":"https://huggingface.co/papers/2608.24680","date":"2026-08-26","title":"Game2World Engine: Unlocking In-the-Wild Gameplay Videos for World Model Training","announceDate":"2026-08-26","upvotes":7,"pdf":"https://arxiv.org/pdf/2608.24680.pdf","url":"https://arxiv.org/abs/2608.24680","arxiv":"https://arxiv.org/abs/2608.24680","tags":["LLM Training","Evaluation","World Model"],"id":"arxiv:2608.24680","abstract":"Video games provide a scalable source of training data for video world models, offering diverse environments, complex interactions, and abundant in-the-wild gameplay videos. However, raw gameplay footage entangles the game world with screen-space interfaces, introducing game-specific biases and irrelevant dynamics that hinder world-model training. To address this problem, we introduce GameUI-Taxonomy and G2WEngine, a full-stack framework that formalizes gameplay UI grounding and removal. G2WEngine automatically extracts reusable UI assets from real gameplay videos and synthesizes temporally coherent UI overlays on clean footage. Using this engine, we construct Game2World, comprising 96K synthetic paired videos with precise reconstruction targets and 1,079 in-the-wild clips from 303 games for realistic evaluation. Its asset library contains 5,132 verified UI elements across 21 taxonomy ca"},{"source":"arxiv","topics":["Evaluation","Reflection"],"authors":["Zae Myung Kim","Young-Jun Lee","Seungyeon Jwa","Dongyeop Kang"],"submittedDate":"2026-08-25","hfUrl":"https://huggingface.co/papers/2608.24735","date":"2026-08-26","title":"Meta$^n$: Recursive Self-Improvement through Emergent Depth","announceDate":"2026-08-26","upvotes":3,"pdf":"https://arxiv.org/pdf/2608.24735.pdf","url":"https://arxiv.org/abs/2608.24735","arxiv":"https://arxiv.org/abs/2608.24735","tags":["Evaluation","Reflection"],"id":"arxiv:2608.24735","abstract":"Self-improving LLM agents refine answers, not the process that produces those answers. Systems that add a meta-level hold that level fixed, and those that edit themselves must leave part of their own editing machinery untouched to stay stable, capping the meta-depth they realize at roughly two. We present Meta$^n$, which keeps the meta-operation fixed and recurses on its input instead. That operation, $Ω$, is applied repeatedly to its own products, reading the traces of the solver stack below together with the code that produced them, then writing the next layer as a strategic pre-process and a library of callable helpers. Because $Ω$ never changes, it cannot destabilize the system, and because its input strictly grows, each layer reasons from a higher vantage than the last. Depth is set by convergence rather than fixed in advance, and an evolutionary archive searches over layer chains. "},{"source":"arxiv","topics":["LLM Training","Evaluation"],"authors":["Andreas Hochlehnert","Marianna Nezhurina","Mehdi Cherti","Andrej Radonjic","Thaddäus Wiedemer","Christoph Schuhmann","Romain Beaumont","Wieland Brendel","Bernhard Schölkopf","A. Sophia Koepke","Jenia Jitsev","Matthias Bethge"],"submittedDate":"2026-08-25","hfUrl":"https://huggingface.co/papers/2608.24845","date":"2026-08-26","title":"LAION-BVD: A 10-Million-Hour Open Video Dataset for Multimodal Pre-training","announceDate":"2026-08-26","upvotes":3,"pdf":"https://arxiv.org/pdf/2608.24845.pdf","url":"https://arxiv.org/abs/2608.24845","arxiv":"https://arxiv.org/abs/2608.24845","tags":["LLM Training","Evaluation"],"id":"arxiv:2608.24845","abstract":"We present LAION-BVD, a large-scale open video dataset for multimodal learning, which contains 1.3B platform-specific video URLs collected from CommonCrawl. From these, we download 80M videos with a total duration of 10 million hours. The dataset is designed for multimodal pre-training across the video, audio, and image modalities. Using content-aware scene detection, we extract clips for which we synthetically generate video and audio captions. Models trained on these data achieve competitive performance on standard video-text and audio-text benchmarks, with consistent improvements as training or model scale increases. Additionally, we explore video frames as an alternative source of image-text data by extracting scene-changing frames. These frames exhibit a visual distribution distinct from standard web image corpora, and models trained on this dataset achieve strong image-text retriev"},{"source":"arxiv","topics":["Agentic Search","Post-Training","Hallucination","Evaluation"],"authors":["Boyang Liu","Senjie Jin","Peixin Wang","Zhangyue Yin","Yibo Wang","Yuhao Zhou","Xinbing Liang","Shizheng Zhu","Yuhui Wang","Jingqi Tong","Zhiheng Xi","Jiazheng Zhang","Clive Bai","Clarenceai","Blaze Chen","Tao Gui","Qi Zhang","Xuanjing Huang"],"submittedDate":"2026-08-25","hfUrl":"https://huggingface.co/papers/2608.24794","date":"2026-08-26","title":"CAFE: Self-Improving Search Agents Need Co-Evolving Feedback","announceDate":"2026-08-26","upvotes":2,"pdf":"https://arxiv.org/pdf/2608.24794.pdf","url":"https://arxiv.org/abs/2608.24794","arxiv":"https://arxiv.org/abs/2608.24794","tags":["Agentic Search","Post-Training","Hallucination","Evaluation"],"id":"arxiv:2608.24794","abstract":"Outcome-supervised search agents learn when and how to retrieve evidence, but terminal rewards neither localize intermediate errors nor redirect an ongoing trajectory before those errors compound. Treating corrective feedback as a learned in-trajectory intervention couples the two roles: the agent must decide when to request and use feedback, while the critic must infer useful corrections from outcome-confounded rollouts whose failure patterns shift as the agent improves. We introduce CAFE (Coupled Agent--Feedback Evolution), a framework in which a shared-parameter model alternates between search-agent and critic roles. CAFE initializes feedback-conditioned recovery from trajectories built around the base agent's own failures, then couples online and offline optimization. During online RL, a comparative feedback estimate uses a prompt-level call--skip success gap to shape request returns"},{"source":"arxiv","topics":["Post-Training","LLM Training","Reasoning","Evaluation","Alignment","Reflection","World Model"],"authors":["Abdulhady Abas Abdullah","Erik Cambria","Milena Zivkovic"],"submittedDate":"2026-08-25","date":"2026-08-26","title":"Neurosymbolic Alignment for Physiologically-Safe Clinical Language Models","announceDate":"2026-08-26","upvotes":0,"pdf":"https://arxiv.org/pdf/2608.24534.pdf","url":"https://arxiv.org/abs/2608.24534","arxiv":"https://arxiv.org/abs/2608.24534","tags":["Post-Training","LLM Training","Reasoning","Evaluation","Alignment"],"id":"arxiv:2608.24534","abstract":"Clinical LLMs can generate recommendations that are factually plausible yet physiologically unsafe. We investigate whether safety alignment can be improved by grounding preference optimization in structured physiological knowledge rather than text-only supervision. Methods: We propose Neurosymbolic Alignment, a training-time framework that couples a 7B clinical LLM with an HGNN-based Physiological World Model over an 847K-node biomedical knowledge graph. Candidate responses are scored using homeostatic constraints, multi-hop path plausibility, and drug-interaction penalties, and the resulting rankings drive iterative on-policy ORPO updates. Evaluation is performed on the Clinical Safety Benchmark (CSB), a 2,500-scenario benchmark for physiological constraint violations in generative clinical reasoning. Results: Relative to ORPO, the proposed method improves CSS from 69.5% to 90.8% (+21.3"},{"source":"arxiv","topics":["Agent Safety","Post-Training","LLM Training","Evaluation","Fine-tuning","RL for LLM"],"authors":["Houcheng Jiang","Boxuan Zhang","Qiyong Zhong","Junfeng Fang","Xiang Wang","Xiangnan He"],"submittedDate":"2026-08-25","date":"2026-08-26","title":"RePolicy: Reinforcement Learning for Safety-Policy Invocation in Agent Safeguards","announceDate":"2026-08-26","upvotes":0,"pdf":"https://arxiv.org/pdf/2608.24275.pdf","url":"https://arxiv.org/abs/2608.24275","arxiv":"https://arxiv.org/abs/2608.24275","tags":["Agent Safety","Post-Training","LLM Training","Evaluation","Fine-tuning"],"id":"arxiv:2608.24275","abstract":"Safeguarding language model agents requires assessing complete execution trajectories under context-dependent safety policies. Existing policy-aware safeguards mainly rely on prompting or supervised fine-tuning, limiting their ability to adapt to unseen trajectories and changing policy contexts. We propose RePolicy, an agent safeguard that learns safety-policy invocation through reinforcement learning. Given an agent trajectory and a dynamic policy library, RePolicy invokes the applicable policy and uses its content to produce a policy-grounded rationale and safety judgment. We construct PolicyTraj-20K to support supervised initialization, followed by GRPO with verifiable rewards and policy-context perturbation. Experiments across six agent safety benchmarks show that RePolicy achieves strong overall safety-detection performance and robust policy invocation under varying policy contexts."},{"source":"arxiv","topics":["Multi-Agent","Tool Use","Reasoning","Planning","Code Agent","Agent Framework"],"authors":["Yuchen Xia","Michael Weyrich","Nasser Jazdi","Johannes Stümpfle","Johannes Sigel","Akshay Narla","Gavin K. Reynolds","Anna Jawor-Baczynska","Pol Llopart"],"submittedDate":"2026-08-22","date":"2026-08-26","title":"LLM Agents Perform Controlled Experiments Using Simulation Models","announceDate":"2026-08-26","upvotes":0,"pdf":"https://arxiv.org/pdf/2608.23622.pdf","url":"https://arxiv.org/abs/2608.23622","arxiv":"https://arxiv.org/abs/2608.23622","tags":["Multi-Agent","Tool Use","Reasoning","Planning","Code Agent"],"id":"arxiv:2608.23622","abstract":"Large language models (LLMs) have shown strong capabilities in reasoning, planning, and tool use, but many scientific and engineering tasks require more than plausible text and code generation. They require understanding how a system responds to intervention, which in practice depends on controlled experimentation. In this work, we propose a multi-agent framework that enables LLM agents to conduct controlled experiments with scientific simulation models for pharmaceutical process design. Given a user query and a baseline configuration, the system constructs a structured task representation, designs experiments, executes comparative simulation, interprets the resulting outcomes, and synthesizes evidence-based recommendations for process parameter optimization. By coupling language models with high-fidelity simulation models in an interactive agent framework, the proposed system supports r"},{"source":"arxiv","topics":["VLM Training","Multi-Agent","Reasoning","Planning","Evaluation","Agent Framework"],"authors":["Yuchuan Wu","Xuan Luo","Yinglian Zhu","Meng Fang","Xiangyang Xue","Bin Li"],"submittedDate":"2026-08-25","date":"2026-08-26","title":"SAGE: From Direct Answering to Evidence-Grounded Inference for Chinese Ancient Document Understanding","announceDate":"2026-08-26","upvotes":0,"pdf":"https://arxiv.org/pdf/2608.24011.pdf","url":"https://arxiv.org/abs/2608.24011","arxiv":"https://arxiv.org/abs/2608.24011","tags":["VLM Training","Multi-Agent","Reasoning","Planning","Evaluation"],"id":"arxiv:2608.24011","abstract":"Chinese ancient document understanding demands complex visual, linguistic, and historical reasoning. Current Large Vision-Language Models (LVLMs) typically rely on an opaque, single-pass generation paradigm, often producing overconfident and weakly grounded responses. To address this, we propose SAGE, an evidence-grounded multi-agent framework that reformulates Chinese ancient document understanding as evidence-grounded inference rather than direct answer generation. SAGE coordinates specialized agents for task-aware planning, tool-mediated evidence acquisition, claim-level verification, and bounded replanning under a constrained shared-state runtime. This design supports bounded evidence seeking, answer revision, and abstention when grounding is insufficient. Experiments on the AncientDoc benchmark show that SAGE consistently outperforms matched direct-answering baselines across three L"},{"source":"arxiv","topics":["Code Agent","Hallucination","Evaluation","Fine-tuning","RL for LLM"],"authors":["Yiwen Zhang","Xiaodong Yan","Zhenyu Huang","Deng Zhao","Liang Jiang","Qing Cui","Zujie Wen","Zhiqiang Zhang","Jun Zhou"],"submittedDate":"2026-08-25","date":"2026-08-26","title":"Robust Code RL via Faulty-Code-Driven Test case Synthesis and Dense Reward Shaping","announceDate":"2026-08-26","upvotes":0,"pdf":"https://arxiv.org/pdf/2608.24135.pdf","url":"https://arxiv.org/abs/2608.24135","arxiv":"https://arxiv.org/abs/2608.24135","tags":["Code Agent","Hallucination","Evaluation","Fine-tuning","RL for LLM"],"id":"arxiv:2608.24135","abstract":"Reinforcement learning from verifiable rewards (RLVR) has emerged as a pivotal technique for enhancing the code generation capabilities of Large Language Models (LLMs). However, the efficacy of RLVR in coding implementations is fundamentally limited by the comprehensiveness of test cases, because insufficient test coverage in code validation often causes false positives, further leading to reward hacking and policy degradation. To mitigate the reward bias stemming from the suboptimal quality of current automated generation methods, we propose the RobustTests framework, which introduces a faulty-code-driven test case synthesis strategy that leverages \"near correct\" faulty codes to guide the model in precisely capturing latent logical discrepancies and further integrates validator agents with behavioral feature clustering to facilitate the granular filtering of invalid and redundant test c"},{"source":"arxiv","topics":["Agent Safety","Post-Training","Reasoning","Computer Use","Evaluation"],"authors":["Guo Gan","Yilun Zhao","Cong Chen","Jinbiao Wei","Tingyu Song","Zheyuan Yang","Lin Fu","Hong Zhou"],"submittedDate":"2026-08-25","date":"2026-08-26","title":"Are Android GUI Agents Robust Against Runtime Anomalies? AnTrap: Evaluating Agents in Dynamic Adversarial Environments","announceDate":"2026-08-26","upvotes":0,"pdf":"https://arxiv.org/pdf/2608.24099.pdf","url":"https://arxiv.org/abs/2608.24099","arxiv":"https://arxiv.org/abs/2608.24099","tags":["Agent Safety","Post-Training","Reasoning","Computer Use","Evaluation"],"id":"arxiv:2608.24099","abstract":"GUI agents often encounter dynamic anomalies when deployed on Android devices, from unexpected pop-ups to action misuse, yet existing benchmarks lack systematic evaluation of agent robustness against runtime anomalies. We introduce AnTrap, a comprehensive benchmark that injects dynamic perturbations into agent execution trajectories. We propose a taxonomy organizing real-world anomalies into four layers (State, Thinking, Action and Round) with ten fine-grained subcategories, and develop a construction pipeline that preserves task solvability while introducing realistic adversarial conditions. Evaluating 16 leading GUI models, we reveal universal vulnerability to dynamic anomalies, with even the strongest models suffering significant performance degradation. Furthermore, we conduct GRPO training in both original and adversarial environments to validate our benchmark, separating environmen"},{"source":"arxiv","topics":["Reasoning","Computer Use","Evaluation","Alignment","Reflection"],"authors":["Yijie Ma","Chaoyue Niu","Fan Wu","Guihai Chen"],"submittedDate":"2026-08-25","date":"2026-08-26","title":"Reflection with Action-Induced Visual Differences for Desktop GUI Agents","announceDate":"2026-08-26","upvotes":0,"pdf":"https://arxiv.org/pdf/2608.24015.pdf","url":"https://arxiv.org/abs/2608.24015","arxiv":"https://arxiv.org/abs/2608.24015","tags":["Reasoning","Computer Use","Evaluation","Alignment","Reflection"],"id":"arxiv:2608.24015","abstract":"The Planner-Operator-Reflector (POR) framework is widely used in GUI agents to maintain objective alignment in complex tasks through modular collaboration. However, desktop GUIs introduce a key challenge: large, dense interfaces often exhibit subtle or scattered state changes, placing most of the burden on the reflector, which must compare pre- and post-action screens, while the planner and operator reason over a single state. Existing reflectors collapse change detection and outcome verification into one step, leaving evidence implicit and yielding weakly grounded decisions. To address this limitation, we propose Evidence-First Reflection (EFR), a two-stage reflector that explicitly decouples action-induced visual differences extraction from outcome verification. EFR identifies the action location and candidate changed regions with Set-of-Marks annotations, describes and filters action-"},{"source":"arxiv","topics":["Multi-Agent","Reasoning","Planning","Evaluation","Agent Framework"],"authors":["Muhammad Tayyab Khan","Lequn Chen","Wenhe Feng","Seung Ki Moon"],"submittedDate":"2026-08-25","date":"2026-08-26","title":"Design-to-Plan: A Large Language Model-Based Multi-Agent Framework for Manufacturing Process Planning from 3D CAD Models and 2D Engineering Drawings","announceDate":"2026-08-26","upvotes":0,"pdf":"https://arxiv.org/pdf/2608.24039.pdf","url":"https://arxiv.org/abs/2608.24039","arxiv":"https://arxiv.org/abs/2608.24039","tags":["Multi-Agent","Reasoning","Planning","Evaluation","Agent Framework"],"id":"arxiv:2608.24039","abstract":"Manufacturing process planning transforms heterogeneous design information into coherent manufacturing decisions. However, existing approaches focus on isolated subtasks, such as feature recognition, drawing interpretation, or tool selection, and struggle to support the full reasoning chain from design artifacts to process plans. This is critical when planning must interpret 3D CAD models, 2D engineering drawings, materials, and domain-specific rules. To address this gap, this paper presents Design-to-Plan, a large language model (LLM)-based multi-agent framework for end-to-end manufacturing process planning. An orchestrator coordinates specialized agents for 3D feature recognition, 2D drawing analysis, 2D-3D context fusion, knowledge retrieval, process sequencing, tool selection, and report generation. Rather than using LLMs as standalone text generators, the framework deploys them as r"},{"source":"arxiv","topics":["Post-Training","Reasoning","Evaluation","Alignment","Reflection"],"authors":["Kaiyuan Liu","Ziyuan Zhuang","Rongxiang Weng","Jieping Ye"],"submittedDate":"2026-08-25","date":"2026-08-26","title":"RecurSE: Bounded Recursive Self-Evaluation for LLM Rubric Judges","announceDate":"2026-08-26","upvotes":0,"pdf":"https://arxiv.org/pdf/2608.24231.pdf","url":"https://arxiv.org/abs/2608.24231","arxiv":"https://arxiv.org/abs/2608.24231","tags":["Post-Training","Reasoning","Evaluation","Alignment","Reflection"],"id":"arxiv:2608.24231","abstract":"LLM-as-judge is essential for evaluating open-ended text and steering post-training, yet improving the judge itself typically relies on expensive annotations, reward models, or distillation from stronger teachers. In this work, we eliminate external gold supervision from the RL training reward: the model's own evaluative capability generates learning signals for its optimization -- a closed-loop setting of bounded recursive self-improvement (RSI) termed Recursive Self-Evaluation (RecurSE). We study two central questions: when can self-improvement occur, and when must it stop? First, RecurSE pairs a trainable judge evaluating candidate responses under per-rule rubrics (Pass 1) with a synchronized policy-copy checker that audits the judge's reasoning against meta-rubrics to supply a scalar process reward (Pass 2). To enable learning, interface decoupling structurally isolates the checker's"},{"source":"arxiv","topics":["VLM Training","Reasoning","Hallucination","Alignment","Interpretability"],"authors":["Alexis Ivan Escamilla-Lopez","Gilberto Ochoa-Ruiz","Salvador Hinojosa","Sharib Ali"],"submittedDate":"2026-08-24","date":"2026-08-26","title":"LUX: A Lesion-Aware Graph-Conditioned Visual - Language Architecture for Explainable Endoscopic Captioning","announceDate":"2026-08-26","upvotes":0,"pdf":"https://arxiv.org/pdf/2608.23853.pdf","url":"https://arxiv.org/abs/2608.23853","arxiv":"https://arxiv.org/abs/2608.23853","tags":["VLM Training","Reasoning","Hallucination","Alignment","Interpretability"],"id":"arxiv:2608.23853","abstract":"The interpretation of endoscopic imagery in ulcerative colitis is complex and subjective, with variability in human assessment and subtle mucosal inflammation. Although deep learning has advanced automated analysis, most vision-language models rely on global visual embeddings that overlook the localized and relational nature of pathological evidence, limiting clinical reliability and interpretability. We introduce LUX (Lesion-aware Unified eXplainable captioning), a graph-conditioned vision-language architecture for explainable endoscopic image captioning. LUX constructs a lesion-centric scene graph from Grad-CAM and CBAM activation maps, representing pathological regions as nodes and encoding their spatial and clinical relationships. These graph embeddings are integrated into the cross-attention layers of a T5 decoder, enabling generated words to attend to specific lesion nodes rather t"},{"source":"arxiv","topics":["VLM Training","Reasoning","Evaluation","Alignment"],"authors":["Siyao Yan","Bo Han","Jisheng Dang","Bimei Wang","Shude Wang","Hong Peng","Yulan Guo","Jianhuang Lai","Bin Hu","Tat-SengChua"],"submittedDate":"2026-08-25","date":"2026-08-26","title":"PhysMLLMs: Spatial Priors for Unified Referring Segmentation and Grounded Reasoning of Images and Videos","announceDate":"2026-08-26","upvotes":0,"pdf":"https://arxiv.org/pdf/2608.24574.pdf","url":"https://arxiv.org/abs/2608.24574","arxiv":"https://arxiv.org/abs/2608.24574","tags":["VLM Training","Reasoning","Evaluation","Alignment"],"id":"arxiv:2608.24574","abstract":"Video multimodal large language models support language guided video segmentation, but they often show spatio temporal inconsistencies, e.g., jitter, drift, and identity switches. These failures are more common when targets are partly hidden or when similar objects appear nearby.One likely reason is that current training lacks explicit spatial priors, which makes it difficult to maintain stable spatial identity and shape over time. We present PhysMLLMs, a training-stage prior injection architecture that injects physics-inspired spatial continuity priors into Video MLLMs. PhysMLLMs is designed to encourage more stable object-centered representations by aligning the student global visual representation with a frozen teacher model during training. Our core mechanism, Global Representation Prior Alignment (REPA-Global), distills global visual representations from a frozen DINOv2 teacher usin"},{"source":"arxiv","topics":["LLM Training","Reasoning","Evaluation","Fine-tuning"],"authors":["Qinglin Ye","Zhiyuan Gu","Jingjie Xia","Yiheng Zhang","Kaiyan Zhao","Shunchao Zheng","Yuhang Mu","Wenchao Du","Yiming Wang"],"submittedDate":"2026-08-25","date":"2026-08-26","title":"OPDSearch+: On-Policy Distillation with RL Refinement for Search-Augmented Reasoning","announceDate":"2026-08-26","upvotes":0,"pdf":"https://arxiv.org/pdf/2608.24310.pdf","url":"https://arxiv.org/abs/2608.24310","arxiv":"https://arxiv.org/abs/2608.24310","tags":["LLM Training","Reasoning","Evaluation","Fine-tuning"],"id":"arxiv:2608.24310","abstract":"Search-augmented reasoning remains difficult for small language models. On-policy distillation (OPD) from trained teachers offers a promising direction, but suffers from two issues: (1) high-quality multi-turn search trajectories depend on dynamic retriever responses, making SFT data prohibitively expensive to collect at scale; (2) task-specifically trained teachers incur substantial training cost, while directly applying OPD with an off-the-shelf teacher without task-specific fine-tuning constrains the student to the teacher's performance ceiling and suffers from severe training instability. We propose OPDSearch+, the first distillation paradigm that requires no teacher fine-tuning for search-augmented reasoning. We investigate the role of a frozen off-the-shelf instruct model as the teacher in on-policy distillation, and reveal a key insight: the teacher reshapes the student's policy d"},{"source":"arxiv","topics":["Agentic RAG","Agentic Search","Evaluation","Alignment"],"authors":["Qiuyi Qi","Tian Liang","Jiamu Wang","Jinjian Zhang","Wei Zhou","Pengcheng Zhu","Linjian Mo","Ming Kong","Jie Liu","Qiang Zhu"],"submittedDate":"2026-08-25","date":"2026-08-26","title":"MetaRAG: Belief-Action Aligned Policy Optimization for Agentic RAG","announceDate":"2026-08-26","upvotes":0,"pdf":"https://arxiv.org/pdf/2608.24214.pdf","url":"https://arxiv.org/abs/2608.24214","arxiv":"https://arxiv.org/abs/2608.24214","tags":["Agentic RAG","Agentic Search","Evaluation","Alignment"],"id":"arxiv:2608.24214","abstract":"Agentic retrieval-augmented generation (RAG) requires language models to decide when to continue searching and when to answer. Existing RL-based methods rely on external supervision and overlook the agent's internal belief about whether the current evidence is sufficient. To address this problem, we reformulate the search decision quality as belief-action alignment and propose MetaRAG, a belief-action aligned policy optimization framework for agentic RAG. MetaRAG uses Verify-first Action Generation to elicit an explicit verification process before each actual action, and Internal Belief Probing to estimate the policy model's own answerability belief from the same question-history context. Based on these, MetaRAG derives a consistency reward that is further gated by answer correctness, avoiding reinforcement of internally consistent but incorrect trajectories. The belief probe is used onl"},{"source":"arxiv","topics":["Post-Training","Reasoning","Computer Use","Evaluation"],"authors":["Tao Xiong","Xavier Hu","Wenkai Wang","Qinzhuo Wu","Changqiao Wu","Pengzhi Gao","Wei Liu","Jian Luan","Shengyu Zhang"],"submittedDate":"2026-08-25","date":"2026-08-26","title":"Task-Adaptive Rubrics for GUI Reward Modeling","announceDate":"2026-08-26","upvotes":0,"pdf":"https://arxiv.org/pdf/2608.24174.pdf","url":"https://arxiv.org/abs/2608.24174","arxiv":"https://arxiv.org/abs/2608.24174","tags":["Post-Training","Reasoning","Computer Use","Evaluation"],"id":"arxiv:2608.24174","abstract":"Recent studies on GUI agents have increasingly focused on outcome reward modeling, which assigns outcome rewards by judging whether an executed trajectory satisfies the success criteria implied by the user instruction. Existing GUI reward verifiers, however, often under-specify how these criteria should be constructed for each task instance. Whether using generic rubric structures or implicit model reasoning, their judging criteria are not sufficiently task-adaptive: they can transfer checks across tasks, overlook concrete constraints in the current instruction, or become overly strict by enforcing unstated requirements. To address this limitation, we propose AdaptRubric, a Coarse-to-Fine Rubrics Framework that constructs task-adaptive judging criteria through a category-level coarse stage and an instance-level fine stage. AdaptRubric performs category-level coarse rubric retrieval by ro"},{"source":"arxiv","topics":["Agentic RAG","Agentic Search","Multi-Agent","Code Agent"],"authors":["Andrei Mikhailov","Mikhail Burtsev","Alsu Sagirova"],"submittedDate":"2026-08-24","date":"2026-08-26","title":"MARS: Multi-Specialist LLM Relay System for Competitive Programming","announceDate":"2026-08-26","upvotes":0,"pdf":"https://arxiv.org/pdf/2608.23918.pdf","url":"https://arxiv.org/abs/2608.23918","arxiv":"https://arxiv.org/abs/2608.23918","tags":["Agentic RAG","Agentic Search","Multi-Agent","Code Agent"],"id":"arxiv:2608.23918","abstract":"Large Language Models excel at code generation, yet competitive programming exposes a persistent failure mode: existing multi-agent pipelines distribute work over generic planner, coder, and debugger roles and delegate the choice of algorithmic technique to the backbone alone. We present MARS (Multi-Agent Relay of Specialized LLMs), a prompt-only framework in which each agent is a topic specialist---dynamic programming, graphs, strings, geometry, and so on---grounded by retrieval-augmented generation over an algorithm-theory corpus. Given a problem, retrieval selects a small team of relevant specialists; a starter writes an initial C++17 solution, and each subsequent turn runs the candidate against public examples in a sandbox, lets the active specialist keep, repair, or hand off the draft, and forwards a structured packet to the next specialist. A single infrastructure-fixer pass normal"},{"source":"arxiv","topics":["Post-Training","LLM Training","Evaluation","Fine-tuning"],"authors":["Anh Ta","Junjie Zhu","Shahin Shayandeh"],"submittedDate":"2026-08-24","date":"2026-08-26","title":"PROOF-Gen: From Optimized Data to Better Distillation","announceDate":"2026-08-26","upvotes":0,"pdf":"https://arxiv.org/pdf/2608.23911.pdf","url":"https://arxiv.org/abs/2608.23911","arxiv":"https://arxiv.org/abs/2608.23911","tags":["Post-Training","LLM Training","Evaluation","Fine-tuning"],"id":"arxiv:2608.23911","abstract":"Supervised fine-tuning on teacher-generated trajectories is the standard first stage for distilling tool-calling capabilities into deployable models. Post-training pipelines that drive shipped tool-calling agents re-run this stage on a daily or weekly cadence, paying the frontier-teacher cost each cycle, yet the mechanism is generate-and-filter (keep the teacher's passing trajectories, discard the rest) and each cycle leaves behind the same hard scenarios because failures supply no signal. On τ2-bench, 57% of teacher trials fail, two-thirds of them near-misses (most tool calls correct, undone by one decisive error). We introduce PROOF-Gen (Per-scenario Reflective Optimization to Overcome FailedGeneration), which recovers golden trajectories from these failures via per-scenario prompt optimization. For each failed task, a reflector analyzes the execution trace and evaluation feedback, the"},{"source":"arxiv","topics":["LLM Training","Tool Use","Reasoning","RL for LLM"],"authors":["Zhi Rui Tam","Chieh-Yen Lin","Yun-Nung Chen","Shao-Hua Sun","Hung-yi Lee"],"submittedDate":"2026-08-25","date":"2026-08-26","title":"Joint Optimization of Tool Creation and Use for Large Language Model Agents","announceDate":"2026-08-26","upvotes":0,"pdf":"https://arxiv.org/pdf/2608.24571.pdf","url":"https://arxiv.org/abs/2608.24571","arxiv":"https://arxiv.org/abs/2608.24571","tags":["LLM Training","Tool Use","Reasoning","RL for LLM"],"id":"arxiv:2608.24571","abstract":"Tool-augmented language models are bounded by the APIs humans bothered to write; existing tool-creation systems patch this by prompting a frozen LLM at inference time, leaving the model that writes a tool decoupled from the one that uses it, with no signal that the schemas it produces are schemas it can invoke. We propose SMITH (Schema-grounded Multi-task Iterative Tool Honing), a reinforcement learning framework that jointly trains tool creation and tool use inside a single policy. Each rollout is either a build task (write a tool from a few examples) or a use task (invoke a pooled tool on a held-out question). Three separate reward axes catch schema, code, and outcome failures independently, so each failure mode contributes its own gradient. A 4B Qwen3 trained with SMITH on 13 procedural reasoning tasks with exact verifiers reaches 79.8 macro-average accuracy on held-out tasks, the bes"},{"source":"arxiv","topics":["Reasoning","Hallucination","Evaluation","Fine-tuning"],"authors":["Mengzhu Xu","Jifan Gao","Xia Jiang","Yaoxin Wu","Xi Long"],"submittedDate":"2026-08-25","date":"2026-08-26","title":"Right Diagnoses, Decorative Reasoning:A Perturbation Audit of Medical Chain-of-Thought","announceDate":"2026-08-26","upvotes":0,"pdf":"https://arxiv.org/pdf/2608.24790.pdf","url":"https://arxiv.org/abs/2608.24790","arxiv":"https://arxiv.org/abs/2608.24790","tags":["Reasoning","Hallucination","Evaluation","Fine-tuning"],"id":"arxiv:2608.24790","abstract":"Clinicians read chain-of-thought (CoT) rationales as evidence of medical reasoning, but whether the visible chain plays that role is rarely tested. General-domain CoT-faithfulness probes ignore clinical cost, and medical LLM evaluations treat the chain as a black box. We close this gap with a medical perturbation audit: a 30-operator battery edits both the chain and the question with clinically motivated operators (severity reversal, negation flip, demographic swap, evidence ablation), paired with a chain-update times answer-flip joint analysis that classifies each model by its failure mode. Applied to 14 LLMs on four medical QA benchmarks, three independent tests converge: the Chain-Decoupling Rate (CDR; chain does not register the edit and the answer does not flip) is 72.9% panel-wide on clinically meaningful destructive edits, chain corruption leaves accuracy unchanged, and removing C"},{"source":"arxiv","topics":["Reasoning","Hallucination","Evaluation","RL for LLM"],"authors":["Qiming Xie","Wenjie Zheng","Xiangqing Shen","Rui Xia"],"submittedDate":"2026-08-25","date":"2026-08-26","title":"FARCA: Fact-Aligned Reliability-Aware Credit Assignment for Reinforcement Learning with Factual Supervision","announceDate":"2026-08-26","upvotes":0,"pdf":"https://arxiv.org/pdf/2608.24350.pdf","url":"https://arxiv.org/abs/2608.24350","arxiv":"https://arxiv.org/abs/2608.24350","tags":["Reasoning","Hallucination","Evaluation","RL for LLM"],"id":"arxiv:2608.24350","abstract":"To reduce the hallucination risk caused by outcome-driven rewards in large language models trained through reinforcement learning with verifiable rewards, existing mitigation approaches introduce process-level factual supervision. However, due to coarse-grained aggregation of factual signals and the lack of reliability assessment for these signals, they create a mismatch between fact verification and policy updates. We term this noisy factual credit assignment and decompose it into two aspects: credit localization ambiguity and credit reliability ambiguity. To address these issues, we propose FARCA (Fact-Aligned Reliability-Aware Credit Assignment), a policy optimization framework that transforms factual supervision into localized, reliability-weighted token-level training signals. FARCA achieves fine-grained credit localization by aligning the granularity of fact verification with that "},{"source":"arxiv","topics":["Agentic RAG","Agentic Search","Post-Training","Hallucination"],"authors":["Jiongxiao Wang","Dingli Ma","Chaoqun Ni"],"submittedDate":"2026-08-24","date":"2026-08-26","title":"Generating Biomedical Fact-Checking Reports with RL-Enhanced Agentic Search","announceDate":"2026-08-26","upvotes":0,"pdf":"https://arxiv.org/pdf/2608.23811.pdf","url":"https://arxiv.org/abs/2608.23811","arxiv":"https://arxiv.org/abs/2608.23811","tags":["Agentic RAG","Agentic Search","Post-Training","Hallucination"],"id":"arxiv:2608.23811","abstract":"Automated fact-checking is essential for ensuring the reliability of public health information, yet the biomedical domain poses unique challenges. Validating biomedical claims requires rigorous interpretation of scientific literature, assessment of retrieved evidence, and comprehensive justification toward the conclusion. Although Large Language Models (LLMs) enhanced by Retrieval-Augmented Generation (RAG) and agentic search perform automated fact-checking in a retrieve-then-verify paradigm, current methods still output isolated prediction labels, lacking explanatory depth and offers limited utility for human understanding. To bridge this gap, we introduce an LLM-based agent named BioCheck Agent that generates structured biomedical fact-checking reports with agentic search. Rather than merely outputting supported or refuted labels, our agent synthesizes final conclusions with retrieved "},{"source":"arxiv","topics":["Post-Training","LLM Training","Interpretability","Fine-tuning"],"authors":["Hang Chen","Jiaying Zhu","Wenya Wang"],"submittedDate":"2026-08-25","date":"2026-08-26","title":"Beyond Static Interpretability: Anticipating Post-SFT Mechanisms from Pre-SFT Parameters for Better Tuning","announceDate":"2026-08-26","upvotes":0,"pdf":"https://arxiv.org/pdf/2608.24482.pdf","url":"https://arxiv.org/abs/2608.24482","arxiv":"https://arxiv.org/abs/2608.24482","tags":["Post-Training","LLM Training","Interpretability","Fine-tuning"],"id":"arxiv:2608.24482","abstract":"Mechanistic Localization bridges mechanistic interpretability and post-training optimization by isolating critical parameters via interpretative approaches and then guiding parameter-efficient Supervised Fine-Tuning (SFT) in a ``locating-then-tuning'' paradigm. However, due to the retrospective nature of mechanistic interpretability, directly interpreting pre-SFT models introduces misleading conclusions. Specifically for novel tasks, initially identified neurons differ drastically from those governing the final model, introducing biases that actively disrupt SFT. To address this, we propose a forward-looking localization framework that accurately estimates the post-SFT interpretability state using only pre-SFT parameters and the target dataset. Theoretically, we model SFT as a continuous parameter evolution, leveraging Taylor expansion to rigorously bridge the post-tuning mechanistic obj"},{"source":"arxiv","topics":["Agent Safety","Alignment","Interpretability","Fine-tuning"],"authors":["Anjun Gao","Yueyang Quan","Yufei Xia","Zhuqing Liu","Minghong Fang"],"submittedDate":"2026-08-25","date":"2026-08-26","title":"NeuronGuard: Robust LLM Safety Alignment via Ablation-Aware Safety Signal Redistribution","announceDate":"2026-08-26","upvotes":0,"pdf":"https://arxiv.org/pdf/2608.23959.pdf","url":"https://arxiv.org/abs/2608.23959","arxiv":"https://arxiv.org/abs/2608.23959","tags":["Agent Safety","Alignment","Interpretability","Fine-tuning"],"id":"arxiv:2608.23959","abstract":"Safety alignment in large language models (LLMs) remains brittle against a growing spectrum of attacks. Jailbreak attacks bypass safety mechanisms through crafted prompts, while neuron-level attacks directly prune safety-critical neurons post-deployment. Both exploit a common weakness: safety-relevant information concentrates in a sparse neuron subset. We present NeuronGuard, a fine-tuning-stage defense that simultaneously hardens LLMs against both attack classes by redistributing safety signals across a broader set of neurons. NeuronGuard dynamically identifies safety-critical neurons via periodically refreshed per-layer linear classifiers, forces refusal behavior under deliberate neuron ablation, and applies KL-divergence regularization for distributional consistency. A randomized gradient projection strategy preserves downstream task utility by resolving conflicts between the defense "},{"source":"arxiv","topics":["Post-Training","Evaluation","Reflection","Data Engine"],"authors":["Yang Yu","Yilin Jiang","Zexuan Fei","Yiming Luo","Xingkai Song","Kaiyi Huang","Aimin Zhou","Xin Lin","Fei Tan"],"submittedDate":"2026-08-24","date":"2026-08-26","title":"ADE: Agentic Data Evolution Framework for Human-Centered Objectives","announceDate":"2026-08-26","upvotes":0,"pdf":"https://arxiv.org/pdf/2608.23719.pdf","url":"https://arxiv.org/abs/2608.23719","arxiv":"https://arxiv.org/abs/2608.23719","tags":["Post-Training","Evaluation","Reflection","Data Engine"],"id":"arxiv:2608.23719","abstract":"Aligning large language models to human-centered objectives is difficult when targets are non-executable and context-dependent, limiting reliable verification and scalable supervision. Although synthetic data expands coverage, weak verification shifts the bottleneck from generation to selection. Noisy signals destabilize iterative refinement and can cause silent regressions. We propose Agentic Data Evolution (ADE), a data-centric framework that organizes synthetic supervision as evolving data snapshots. ADE improves data snapshots through a closed-loop Observation-Variation-Selection (OVS) procedure, where a steady-state admission mechanism acts as a quality ratchet that conservatively gates updates for sustained cross-round improvement. We validate these improvements through complementary intrinsic trend tracking and extrinsic post-training evaluation. On DEV300, ADE raises the intrinsi"},{"source":"arxiv","topics":["Multi-Agent","Hallucination","Evaluation","Agent Framework"],"authors":["Eran Hirsch","David Wan","Han Wang","Elias Stengel-Eskin","Mohit Bansal","Ido Dagan"],"submittedDate":"2026-08-25","date":"2026-08-26","title":"Who is the Agent to Blame? Localizing Faithfulness and Citation Mistakes in Agentic Deep Research","announceDate":"2026-08-26","upvotes":0,"pdf":"https://arxiv.org/pdf/2608.24306.pdf","url":"https://arxiv.org/abs/2608.24306","arxiv":"https://arxiv.org/abs/2608.24306","tags":["Multi-Agent","Hallucination","Evaluation","Agent Framework"],"id":"arxiv:2608.24306","abstract":"Deep research (DR) systems produce long-form cited reports by orchestrating multiple agents that search and synthesize information from the web. Citations are the primary mechanism for evaluating the faithfulness of these reports, yet current DR systems exhibit poor citation recall. Moreover, improving citation recall is challenging because DR systems are complex multi-agent architectures where information passes through agents like a telephone game, and both content and citations can get corrupted along the way. We propose an evaluation method that pinpoints which agent introduced each error by locally testing agent invocations for faithfulness and verifiability relative to their own inputs. Furthermore, we propose a four-type taxonomy to categorize the discovered errors: hallucination, uncited input reliance, uncited output, or insufficient citations. Applying our method to three top-r"},{"source":"arxiv","topics":["Reasoning","Planning","Evaluation","RL for LLM"],"authors":["Zihan Wang","Bai Huang","Yang Guan","Xiao Li","Haoyu Xu","Naizheng Wang","Shengbo Eben Li"],"submittedDate":"2026-08-25","date":"2026-08-26","title":"NeuralParker: A Reinforcement Learning Planner for Irregular Parking Environments","announceDate":"2026-08-26","upvotes":0,"pdf":"https://arxiv.org/pdf/2608.24485.pdf","url":"https://arxiv.org/abs/2608.24485","arxiv":"https://arxiv.org/abs/2608.24485","tags":["Reasoning","Planning","Evaluation","RL for LLM"],"id":"arxiv:2608.24485","abstract":"Automated parking commonly assumes marked slots and short approach maneuvers. Delivery and service vehicles, however, may need to reach an operator-specified pose in an irregular bounded environment from a distant start. Existing learning-based parking planners often rely on local observations, which can restrict long-range route reasoning. To address this problem, we present NeuralParker, a reinforcement learning-based hybrid planner for arbitrary-pose parking. NeuralParker encodes full-environment obstacle and boundary geometry in a target-relative vertex representation, allowing the policy to retain route-defining context throughout the approach. It further couples a learned curvature--length arc policy with an in-loop terminal ensemble that selects from diverse cubic Hermite connections using a curvature-regularized cost. We also establish factorial and long-range route-choice benchm"},{"source":"arxiv","topics":["Multi-Agent","Code Agent","Evaluation","Agent Framework"],"authors":["Tianyu Wang","Wenjie Wang","Jianguo Yao","Haibing Guan","Xijun Li"],"submittedDate":"2026-08-23","date":"2026-08-26","title":"FPGAgent: An LLM-Assisted Framework for Autonomous HLS Code Generation and Verification in FPGA Environments","announceDate":"2026-08-26","upvotes":0,"pdf":"https://arxiv.org/pdf/2608.23630.pdf","url":"https://arxiv.org/abs/2608.23630","arxiv":"https://arxiv.org/abs/2608.23630","tags":["Multi-Agent","Code Agent","Evaluation","Agent Framework"],"id":"arxiv:2608.23630","abstract":"Large language models (LLMs) have shown substantial promise for high-level synthesis (HLS) code generation, but most existing approaches validate only simulation or synthesis results. Because of timing and place-and-route constraints, \\emph{HLS code that passes simulation and synthesis may still fail to produce deployable, runnable designs on real FPGA platforms}. Moreover, the lack of public benchmarks has limited many evaluations to small, self-curated test suites. We propose FPGAgent, a multi-agent framework tailored to real FPGA environments for autonomous HLS coding with end-to-end executability validation. To the best of our knowledge, FPGAgent is \\emph{the first task-specification-to-executable HLS generation framework experimentally validated on a well-established benchmark}. Given a natural-language task specification, FPGAgent injects HLS-specific knowledge and employs evolutio"}],"archive":[],"latestPath":"data/latest.json"};
